from math import sqrt, erf, ceil

def p_two_sided(z):
    return 2 * (1 - 0.5 * (1 + erf(abs(z) / sqrt(2))))

def two_prop_z(x1, n1, x2, n2):
    p1, p2 = x1 / n1, x2 / n2
    p = (x1 + x2) / (n1 + n2)
    se = sqrt(p * (1 - p) * (1 / n1 + 1 / n2))
    z = (p2 - p1) / se
    return p1, p2, z, p_two_sided(z)

print("A %.3f  B %.3f  z=%.2f  p=%.4f" % two_prop_z(1200, 10000, 1290, 10000))

def n_per_group(p, delta, za=1.96, zb=0.8416):  # 유의수준 5%, 검정력 80%
    p2 = p + delta
    return ceil((za + zb) ** 2 * (p * (1 - p) + p2 * (1 - p2)) / delta ** 2)

print("그룹당", n_per_group(0.12, 0.005), "명")
# A 0.120  B 0.129  z=1.93  p=0.0539
