from math import sqrt

def wilson_lower(pos, n, z=1.96):
    if n == 0:
        return 0.0
    p = pos / n
    return (p + z*z/(2*n) - z*sqrt((p*(1-p) + z*z/(4*n)) / n)) / (1 + z*z/n)

for name, (pos, n) in {"A(신작)": (9, 10), "B(인기작)": (820, 1000), "C": (60, 100)}.items():
    print(f"{name}: 단순 비율 {pos/n:.2f}  윌슨 하한 {wilson_lower(pos, n):.2f}")

def decayed(views, half_life=24):  # (몇 시간 전, 열람 수)
    return sum(v * 0.5 ** (h / half_life) for h, v in views)

print("30시간 전 5,000회:", round(decayed([(30, 5000)])), "/ 2시간 전 2,500회:", round(decayed([(2, 2500)])))
